import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'launch.sqlite') }, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  const port = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Launch timeout')), 5000);
    child.stdout.on('data', data => {
      const match = /Workboard listening on port (\\d+)/.exec(data.toString());
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
    child.on('error', reject);
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  if (response.status !== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') throw new Error('Health check failed');
  console.log('npm start with PORT and DB_PATH: health HTTP 200, {\"status\":\"ok\"}');
} finally {
  process.kill(-child.pid, 'SIGTERM');
  await new Promise(resolve => child.on('exit', resolve));
  await rm(directory, { recursive: true, force: true });
}
